import re


def eval_expression(expr):
    """Evaluate an arithmetic expression containing +, -, *, /, and parentheses."""

    if not isinstance(expr, str):
        raise TypeError("expr must be a string")

    token_pattern = re.compile(
        r"\s*(?:(\d+(?:\.\d*)?|\.\d+)|([()+\-*/]))"
    )

    # Tokenize the expression
    tokens = []
    pos = 0

    while pos < len(expr):
        match = token_pattern.match(expr, pos)

        if match is None:
            if expr[pos:].strip():
                raise ValueError(f"Invalid character at position {pos}")
            break

        number, operator = match.groups()
        tokens.append(float(number) if number and "." in number else
                      int(number) if number else operator)
        pos = match.end()

    if not tokens:
        raise ValueError("Expression is empty")

    index = 0

    def parse_expression():
        nonlocal index
        value = parse_term()

        while index < len(tokens) and tokens[index] in ("+", "-"):
            operator = tokens[index]
            index += 1
            right = parse_term()

            if operator == "+":
                value += right
            else:
                value -= right

        return value

    def parse_term():
        nonlocal index
        value = parse_factor()

        while index < len(tokens) and tokens[index] in ("*", "/"):
            operator = tokens[index]
            index += 1
            right = parse_factor()

            if operator == "*":
                value *= right
            else:
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                value /= right

        return value

    def parse_factor():
        nonlocal index

        if index >= len(tokens):
            raise ValueError("Expected a number or parenthesized expression")

        token = tokens[index]

        # Handle unary + and -
        if token == "+":
            index += 1
            return parse_factor()

        if token == "-":
            index += 1
            return -parse_factor()

        if token == "(":
            index += 1
            value = parse_expression()

            if index >= len(tokens) or tokens[index] != ")":
                raise ValueError("Missing closing parenthesis")

            index += 1
            return value

        if isinstance(token, (int, float)):
            index += 1
            return token

        raise ValueError(f"Unexpected token: {token!r}")

    result = parse_expression()

    if index != len(tokens):
        raise ValueError(f"Unexpected token: {tokens[index]!r}")

    return result
